@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    color-scheme: dark light;
    --background: #020617;
    --foreground: #f8fafc;
    --brand: #06b6d4;
    --brand-wordmark-main: #e2e8f0;
    --brand-wordmark-accent: #2fe1c3;
    --brand-wordmark-orbit: rgba(47, 225, 195, 0.5);
    --surface-page: #020617;
    --surface-page-soft: #07111f;
    --surface-panel: rgba(15, 23, 42, 0.78);
    --surface-panel-strong: rgba(2, 6, 23, 0.9);
    --surface-card: rgba(15, 23, 42, 0.72);
    --surface-border: rgba(148, 163, 184, 0.16);
    --surface-border-strong: rgba(34, 211, 238, 0.24);
    --text-main: #f8fafc;
    --text-muted: #cbd5e1;
    --text-soft: #94a3b8;
    --accent-cyan: #22d3ee;
    --accent-emerald: #34d399;
    --accent-violet: #a78bfa;
    --shadow-panel: 0 24px 70px rgba(0, 0, 0, 0.32);
  }

  html.theme-light {
    --background: #f5f8ff;
    --foreground: #020617;
    --brand-wordmark-main: #0f172a;
    --brand-wordmark-accent: #0891b2;
    --brand-wordmark-orbit: rgba(14, 165, 233, 0.42);
    --surface-page: #f7fbff;
    --surface-page-soft: #eef6ff;
    --surface-panel: rgba(255, 255, 255, 0.9);
    --surface-panel-strong: rgba(248, 252, 255, 0.96);
    --surface-card: rgba(255, 255, 255, 0.84);
    --surface-border: rgba(15, 23, 42, 0.12);
    --surface-border-strong: rgba(14, 116, 144, 0.24);
    --text-main: #0f172a;
    --text-muted: #334155;
    --text-soft: #64748b;
    --accent-cyan: #0891b2;
    --accent-emerald: #047857;
    --accent-violet: #6d28d9;
    --shadow-panel: 0 24px 70px rgba(15, 23, 42, 0.1);
  }

  body {
    @apply bg-[var(--background)] text-[var(--foreground)] antialiased;
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  }

  /* Core layout classes */
  .container-shell {
    @apply mx-auto w-full max-w-7xl px-4 md:px-8;
  }
}

@layer components {
  .demo-lab-fullscreen-root,
  .demo-lab-fullscreen-stage {
    min-height: 100vh;
    overflow-y: auto;
    background: #03070f;
  }

  .demo-lab-studio {
    position: relative;
    min-height: calc(100vh - 7rem);
    overflow: hidden;
    border: 1px solid rgba(125, 211, 252, 0.16);
    border-radius: 28px;
    background:
      radial-gradient(circle at 20% 8%, rgba(20, 184, 166, 0.18), transparent 32%),
      radial-gradient(circle at 82% 12%, rgba(168, 85, 247, 0.14), transparent 30%),
      linear-gradient(145deg, rgba(2, 6, 23, 0.98), rgba(8, 13, 31, 0.94));
    box-shadow: 0 32px 120px rgba(0, 0, 0, 0.45);
  }

  .demo-lab-wizard-nav {
    position: sticky;
    top: 0.75rem;
    z-index: 20;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin: clamp(0.75rem, 1.6vw, 1.25rem);
    padding: 0.6rem;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 20px;
    background: rgba(2, 6, 23, 0.78);
    backdrop-filter: blur(18px);
  }

  .demo-lab-wizard-steps {
    display: flex;
    flex: 1 1 auto;
    min-width: 0;
    gap: 0.45rem;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .demo-lab-wizard-steps::-webkit-scrollbar {
    display: none;
  }

  .demo-lab-wizard-nav-back,
  .demo-lab-wizard-step-pill,
  .demo-lab-wizard-next-btn,
  .demo-lab-wizard-primary-cta,
  .demo-lab-wizard-secondary-cta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.45rem;
    border-radius: 999px;
    font-size: 0.72rem;
    font-weight: 900;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .demo-lab-wizard-nav-back,
  .demo-lab-wizard-step-pill,
  .demo-lab-wizard-secondary-cta {
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: rgba(15, 23, 42, 0.72);
    color: #cbd5e1;
  }

  .demo-lab-wizard-nav-back,
  .demo-lab-wizard-step-pill {
    flex: 0 0 auto;
    gap: 0.45rem;
    padding: 0 0.95rem;
  }

  .demo-lab-wizard-step-pill.is-active,
  .demo-lab-wizard-next-btn,
  .demo-lab-wizard-primary-cta {
    border: 1px solid rgba(34, 211, 238, 0.58);
    background: linear-gradient(135deg, #22d3ee, #2dd4bf);
    color: #020617;
    box-shadow: 0 16px 42px rgba(6, 182, 212, 0.22);
  }

  .demo-lab-wizard-step-pill.is-done {
    border-color: rgba(16, 185, 129, 0.42);
    color: #6ee7b7;
  }

  .demo-lab-wizard-step-num {
    display: grid;
    width: 1.35rem;
    height: 1.35rem;
    place-items: center;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.16);
    font-size: 0.65rem;
  }

  .demo-lab-wizard-scene {
    display: grid;
    gap: clamp(1rem, 2vw, 1.5rem);
    align-items: center;
    min-height: calc(100vh - 12rem);
    padding: 0 clamp(0.75rem, 2vw, 1.5rem) clamp(1rem, 2vw, 1.5rem);
  }

  .demo-lab-wizard-scene--toca {
    grid-template-columns: minmax(12rem, 0.8fr) minmax(18rem, 1.35fr) minmax(12rem, 0.75fr);
  }

  .demo-lab-wizard-scene--verifico,
  .demo-lab-wizard-scene--trazo {
    grid-template-columns: minmax(0, 1.35fr) minmax(17rem, 0.8fr);
  }

  .demo-lab-wizard-context,
  .demo-lab-wizard-result-card,
  .demo-lab-wizard-events,
  .demo-lab-wizard-trazo-side,
  .demo-lab-wizard-gano-card {
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 24px;
    background: rgba(15, 23, 42, 0.66);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }

  .demo-lab-wizard-context,
  .demo-lab-wizard-result-card,
  .demo-lab-wizard-events,
  .demo-lab-wizard-trazo-side {
    padding: clamp(1rem, 2vw, 1.35rem);
  }

  .demo-lab-wizard-eyebrow {
    margin: 0;
    color: #67e8f9;
    font-size: 0.7rem;
    font-weight: 900;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }

  .demo-lab-wizard-product-name,
  .demo-lab-wizard-result-status,
  .demo-lab-wizard-gano-header h2 {
    margin: 0.35rem 0 0;
    color: #f8fafc;
    font-size: clamp(1.8rem, 4vw, 4rem);
    font-weight: 950;
    line-height: 0.96;
    letter-spacing: 0;
  }

  .demo-lab-wizard-tagline,
  .demo-lab-wizard-result-desc,
  .demo-lab-wizard-gano-card p {
    color: #94a3b8;
    line-height: 1.6;
  }

  .demo-lab-wizard-center {
    display: grid;
    gap: 1rem;
    justify-items: center;
    min-width: 0;
  }

  .demo-lab-wizard-tap-btn {
    position: relative;
    display: grid;
    width: min(13rem, 58vw);
    height: min(13rem, 58vw);
    place-items: center;
    overflow: hidden;
    border: 1px solid rgba(34, 211, 238, 0.45);
    border-radius: 999px;
    background: radial-gradient(circle, rgba(34, 211, 238, 0.34), rgba(14, 165, 233, 0.12) 48%, rgba(2, 6, 23, 0.85));
    color: #ecfeff;
    font-weight: 950;
    text-transform: uppercase;
    box-shadow: 0 0 80px rgba(6, 182, 212, 0.25);
  }

  .demo-lab-wizard-verticals,
  .demo-lab-wizard-events,
  .demo-lab-wizard-trazo-side {
    display: grid;
    gap: 0.75rem;
    max-height: min(68vh, 42rem);
    overflow-y: auto;
  }

  .demo-lab-wizard-vertical-btn {
    display: grid;
    grid-template-columns: 3.2rem minmax(0, 1fr);
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.6rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 18px;
    background: rgba(15, 23, 42, 0.62);
    color: #cbd5e1;
    text-align: left;
  }

  .demo-lab-wizard-vertical-btn.is-active {
    border-color: rgba(34, 211, 238, 0.55);
    background: rgba(14, 116, 144, 0.22);
    color: #f8fafc;
  }

  .demo-lab-wizard-result-card {
    display: grid;
    justify-items: start;
    align-content: center;
    min-height: 28rem;
  }

  .demo-lab-wizard-result-pills,
  .demo-lab-wizard-gano-cta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
  }

  .demo-lab-wizard-result-pills span,
  .demo-lab-wizard-event {
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 999px;
    background: rgba(2, 6, 23, 0.46);
    color: #cbd5e1;
  }

  .demo-lab-wizard-result-pills span {
    padding: 0.45rem 0.7rem;
    font-size: 0.75rem;
    font-weight: 800;
  }

  .demo-lab-wizard-event {
    display: grid;
    gap: 0.15rem;
    padding: 0.75rem 0.9rem;
    border-radius: 16px;
  }

  .demo-lab-wizard-map-container {
    min-height: 32rem;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 24px;
    background: rgba(2, 6, 23, 0.62);
  }

  .demo-lab-wizard-gano-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.9rem;
    margin-top: 1.5rem;
  }

  .demo-lab-wizard-gano-card {
    padding: 1rem;
  }

  .demo-lab-hub-root {
    min-height: 100vh;
    background: radial-gradient(circle at 16% 8%, rgba(34, 211, 238, 0.16), transparent 28%), #03070f;
    color: #f8fafc;
  }

  html.theme-light .demo-lab-hub-root,
  html[data-theme="light"] .demo-lab-hub-root {
    background: linear-gradient(180deg, #f8fafc 0%, #eef6ff 100%);
    color: #0f172a;
  }

  html.theme-light .demo-lab-hub-root .text-white,
  html.theme-light .demo-lab-hub-root .text-slate-100,
  html[data-theme="light"] .demo-lab-hub-root .text-white,
  html[data-theme="light"] .demo-lab-hub-root .text-slate-100 {
    color: #0f172a;
  }

  html.theme-light .demo-lab-hub-card,
  html.theme-light .demo-lab-hub-nav,
  html.theme-light .demo-lab-hub-pill,
  html[data-theme="light"] .demo-lab-hub-card,
  html[data-theme="light"] .demo-lab-hub-nav,
  html[data-theme="light"] .demo-lab-hub-pill {
    border-color: rgba(148, 163, 184, 0.28);
    background: rgba(255, 255, 255, 0.82);
    color: #0f172a;
  }

  .nexid-enterprise-proof-band {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(17rem, 0.75fr);
    gap: 1rem;
    padding: clamp(1rem, 2.4vw, 1.75rem);
    border: 1px solid rgba(125, 211, 252, 0.18);
    border-radius: 28px;
    background: linear-gradient(135deg, rgba(8, 13, 31, 0.94), rgba(2, 6, 23, 0.98));
    box-shadow: 0 26px 90px rgba(0, 0, 0, 0.28);
  }

  .nexid-enterprise-proof-band__core h2 {
    max-width: 56rem;
    margin: 0.35rem 0 1rem;
    color: #f8fafc;
    font-size: clamp(1.35rem, 2.4vw, 2.4rem);
    font-weight: 950;
    line-height: 1.05;
    letter-spacing: 0;
  }

  .nexid-enterprise-proof-band__core > div,
  .nexid-enterprise-proof-band__steps,
  .nexid-enterprise-proof-band__metrics {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
  }

  .nexid-enterprise-proof-band__core span,
  .nexid-enterprise-proof-band__steps span,
  .nexid-enterprise-proof-band__quote,
  .nexid-enterprise-proof-band__metrics div {
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: rgba(15, 23, 42, 0.62);
    color: #cbd5e1;
  }

  .nexid-enterprise-proof-band__core span,
  .nexid-enterprise-proof-band__steps span {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.65rem;
    border-radius: 999px;
    font-size: 0.78rem;
    font-weight: 800;
  }

  .nexid-enterprise-proof-band__quote {
    padding: 1rem;
    border-radius: 22px;
  }

  .nexid-enterprise-proof-band__metrics,
  .nexid-enterprise-proof-band__steps {
    grid-column: 1 / -1;
  }

  .nexid-enterprise-proof-band__metrics div {
    flex: 1 1 12rem;
    padding: 0.9rem;
    border-radius: 18px;
  }

  .nexid-pricing-page {
    overflow-x: hidden;
    background: linear-gradient(180deg, #020617 0%, #08111f 58%, #030712 100%);
    color: #f8fafc;
  }

  .nexid-pricing-page .container-shell,
  .nexid-pricing-hero,
  .nexid-pricing-grid,
  .nexid-pricing-card,
  .nexid-pricing-compare {
    min-width: 0;
  }

  .nexid-pricing-hero {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(18rem, 0.75fr);
    gap: 1rem;
    align-items: end;
    padding: clamp(2.5rem, 6vw, 5rem) 0 clamp(1.5rem, 3vw, 2.5rem);
  }

  .nexid-pricing-hero h1 {
    margin: 0;
    color: #f8fafc;
    font-size: clamp(2.6rem, 7vw, 5.8rem);
    font-weight: 950;
    line-height: 0.92;
    letter-spacing: 0;
    overflow-wrap: anywhere;
  }

  .nexid-pricing-hero p,
  .nexid-pricing-hero__proof span,
  .nexid-pricing-card > span:not(.nexid-pricing-card__badge) {
    color: #cbd5e1;
    line-height: 1.6;
  }

  .nexid-pricing-hero__proof,
  .nexid-pricing-card,
  .nexid-pricing-compare {
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 24px;
    background: rgba(15, 23, 42, 0.74);
  }

  .nexid-pricing-hero__proof,
  .nexid-pricing-card {
    padding: 1.25rem;
  }

  .nexid-pricing-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1rem;
  }

  .nexid-pricing-card {
    display: flex;
    min-height: 31rem;
    flex-direction: column;
  }

  .nexid-pricing-card h2,
  .nexid-pricing-card > strong {
    color: #f8fafc;
    font-weight: 950;
  }

  .nexid-pricing-card > strong {
    font-size: clamp(1.45rem, 7vw, 2rem);
    overflow-wrap: anywhere;
  }

  .nexid-pricing-card ul {
    display: grid;
    gap: 0.7rem;
    margin: 1.25rem 0;
    padding: 0;
    list-style: none;
  }

  .nexid-pricing-card li {
    display: flex;
    gap: 0.55rem;
    color: #dbeafe;
    line-height: 1.45;
  }

  .nexid-pricing-card > a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    min-height: 2.85rem;
    margin-top: auto;
    border-radius: 999px;
    background: linear-gradient(135deg, #22d3ee, #2dd4bf);
    color: #020617;
    font-size: 0.82rem;
    font-weight: 950;
    text-transform: uppercase;
  }

  .nexid-pricing-compare {
    width: 100%;
    max-width: 100%;
    margin: 1rem 0 2rem;
    overflow-x: auto;
  }

  .nexid-pricing-compare table {
    width: 100%;
    min-width: 760px;
    border-collapse: collapse;
  }

  .nexid-pricing-compare th,
  .nexid-pricing-compare td {
    padding: 1rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.12);
    color: #cbd5e1;
    text-align: left;
    vertical-align: top;
  }

  @media (max-width: 1024px) {
    .demo-lab-wizard-scene--toca,
    .demo-lab-wizard-scene--verifico,
    .demo-lab-wizard-scene--trazo,
    .nexid-enterprise-proof-band,
    .nexid-pricing-hero {
      grid-template-columns: 1fr;
    }

    .demo-lab-wizard-gano-grid,
    .nexid-pricing-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 720px) {
    .demo-lab-studio {
      border-radius: 20px;
    }

    .demo-lab-wizard-nav {
      align-items: stretch;
      flex-direction: column;
      margin: 0.75rem;
    }

    .demo-lab-wizard-gano-grid,
    .nexid-pricing-grid {
      grid-template-columns: 1fr;
    }

    .nexid-pricing-card {
      min-height: auto;
    }

    .nexid-pricing-hero h1 {
      font-size: clamp(2.1rem, 12vw, 3rem);
    }

    .nexid-pricing-compare table {
      min-width: 620px;
    }
  }
}

.brand-lockup {
  --brand-accent: #2fe1c3;
  --brand-mark-bg: linear-gradient(145deg, #0b1220, #111b30);
  --brand-mark-border: rgba(255, 255, 255, 0.14);
  --brand-mark-plate: rgba(47, 225, 195, 0.1);
  --brand-wordmark-main-hi: #ffffff;
  --brand-wordmark-main-lo: #94a3b8;
  --brand-wordmark-accent-hi: #67e8f9;
  --brand-wordmark-accent-lo: #0891b2;
  --brand-wordmark-pulse-duration: 4.2s;
  --brand-wordmark-float-duration: 5.4s;
  --brand-wordmark-pulse-up: -1px;
  --brand-wordmark-float-up: -1.2px;
  --brand-wordmark-float-down: .6px;
  color: var(--brand-wordmark-main);
  isolation: isolate;
  perspective: 720px;
  transform-style: preserve-3d;
}

.brand-wordmark-svg {
  filter: drop-shadow(0 0 18px rgba(47, 225, 195, 0.16));
  overflow: visible;
  transform-origin: left center;
}

.brand-wordmark-shadow {
  opacity: 0.68;
}

.brand-wordmark-text {
  transform-origin: center;
}

.brand-wordmark-text--accent {
  animation: brandAccentGlow 3.8s ease-in-out infinite;
}

.brand-wordmark-orbit {
  transform-origin: 220px 41px;
  animation: brandWordOrbit 5.2s linear infinite;
}

.brand-wordmark-satellite {
  filter: drop-shadow(0 0 10px rgba(47, 225, 195, 0.62));
  transition: transform 0.3s ease, filter 0.3s ease;
}

.brand-lockup:hover .brand-wordmark-text--main {
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.45), 0 0 22px rgba(255, 255, 255, 0.22);
  filter: brightness(1.2);
  transition: text-shadow 0.3s ease, filter 0.3s ease;
}

.brand-lockup:hover .brand-wordmark-text--accent {
  text-shadow: 0 0 14px rgba(47, 225, 195, 0.8), 0 0 28px rgba(47, 225, 195, 0.4);
  filter: brightness(1.3);
  transition: text-shadow 0.3s ease, filter 0.3s ease;
}

.brand-lockup:hover .brand-wordmark-satellite {
  transform: scale(1.18);
  filter: drop-shadow(0 0 15px rgba(47, 225, 195, 0.95));
}

.brand-wordmark-scanline {
  stroke-dasharray: 64 220;
  stroke-dashoffset: 160;
  animation: brandWordScan 3.7s ease-in-out infinite;
}

.brand-mark {
  position: relative;
  isolation: isolate;
  overflow: visible;
  transform-style: preserve-3d;
  box-shadow:
    0 16px 34px rgba(2, 6, 23, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: transform 0.24s ease, box-shadow 0.24s ease, border-color 0.24s ease;
}

.brand-lockup--ripple .brand-mark,
.brand-lockup--pulse .brand-mark {
  animation: brandMarkFloat 5.4s ease-in-out infinite;
}

.brand-lockup:hover .brand-mark {
  animation: none;
  transform: rotateX(12deg) rotateY(-14deg) translateY(-3px) scale(1.06);
  border-color: rgba(34, 211, 238, 0.6) !important;
  box-shadow:
    0 24px 50px rgba(2, 6, 23, 0.55),
    0 0 35px rgba(34, 211, 238, 0.32),
    0 0 15px rgba(47, 225, 195, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.brand-n-path {
  animation: brandNPulse 3.2s ease-in-out infinite;
}
.brand-n-path-stroke {
  animation: brandNStrokePulse 3.2s ease-in-out infinite;
}
.brand-i-path {
  animation: brandIPulse 3.2s ease-in-out infinite;
  animation-delay: 1.6s;
}
.brand-i-path-stroke {
  animation: brandIStrokePulse 3.2s ease-in-out infinite;
  animation-delay: 1.6s;
}

.brand-mark__depth {
  position: absolute;
  inset: 10%;
  z-index: -1;
  border-radius: 1.05rem;
  background: linear-gradient(145deg, rgba(14, 116, 144, 0.42), rgba(15, 23, 42, 0.88));
  filter: blur(0.5px);
  opacity: 0.82;
  transform: translate3d(4px, 5px, -16px);
}

.brand-mark__scan {
  position: absolute;
  inset: 12%;
  z-index: 3;
  border-radius: 1rem;
  pointer-events: none;
  background:
    linear-gradient(110deg, transparent 0 28%, rgba(255, 255, 255, 0.22) 38%, rgba(103, 232, 249, 0.2) 46%, transparent 58% 100%),
    repeating-linear-gradient(0deg, transparent 0 8px, rgba(103, 232, 249, 0.12) 8px 9px);
  mix-blend-mode: screen;
  opacity: 0.58;
  transform: translateX(-70%);
  animation: brandMarkScan 4.8s ease-in-out infinite;
}

.brand-mark__svg {
  position: relative;
  z-index: 2;
  transform: translateZ(12px);
}

.brand-i-head {
  z-index: 5;
}

.brand-i-stem-origin {
  position: absolute;
  z-index: 4;
  right: 24.5%;
  top: 38%;
  width: 7%;
  height: 7%;
  border-radius: 999px;
  background: rgba(47, 225, 195, 0.35);
  box-shadow: 0 0 10px rgba(47, 225, 195, 0.65);
  animation: brandCircuitBlink 2.8s ease-in-out infinite;
}

.brand-i-head-orbit {
  position: absolute;
  z-index: 4;
  right: 12%;
  top: 16%;
  width: 36%;
  height: 36%;
  border: 1px dashed rgba(47, 225, 195, 0.5);
  border-radius: 28%;
  box-shadow: 0 0 16px rgba(47, 225, 195, 0.18);
  animation: brandOrbitPulse 3.6s ease-in-out infinite, brandOrbitRotate 8.5s linear infinite;
}

.brand-i-head--travel {
  position: absolute;
  right: 24.5%;
  top: 38%;
  animation: brandDotTraverse 4.2s cubic-bezier(.48,.03,.49,.96) infinite;
}

.brand-dot {
  position: relative;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
}

.brand-dot__core {
  width: 100%;
  height: 100%;
  border-radius: 999px;
  background: var(--brand-dot-color);
  box-shadow: 0 0 16px -4px var(--brand-dot-glow);
  animation: brandDotPulse 3.2s ease-in-out infinite;
}

.brand-dot__ring {
  position: absolute;
  inset: -8%;
  border-radius: 999px;
  border: 1px solid rgba(47, 225, 195, 0.6);
  pointer-events: none;
}

.brand-lockup--pulse .brand-wordmark-svg {
  animation: brandWordmarkPulse var(--brand-wordmark-pulse-duration) ease-in-out infinite;
}

.brand-lockup--ripple .brand-wordmark-svg {
  animation: brandWordmarkFloat var(--brand-wordmark-float-duration) ease-in-out infinite;
}

.brand-surface-footer .brand-wordmark-svg {
  --brand-wordmark-float-duration: 6s;
}

.brand-surface-loading .brand-wordmark-svg {
  --brand-wordmark-pulse-duration: 2.8s;
  filter: drop-shadow(0 0 20px rgba(47, 225, 195, 0.24));
}

