@keyframes brandOrbitPulse {
  0%, 100% { opacity: .75; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.03); }
}

@keyframes brandOrbitRotate {
  to { rotate: 360deg; }
}

@keyframes brandMarkFloat {
  0%, 100% { transform: rotateX(0deg) rotateY(0deg) translateY(0); }
  35% { transform: rotateX(2.5deg) rotateY(-3.5deg) translateY(-1.2px); }
  68% { transform: rotateX(-1deg) rotateY(2deg) translateY(0.6px); }
}

@keyframes brandMarkScan {
  0%, 28% { transform: translateX(-78%) skewX(-12deg); opacity: 0; }
  42% { opacity: 0.64; }
  58%, 100% { transform: translateX(76%) skewX(-12deg); opacity: 0; }
}

@keyframes brandCircuitBlink {
  0%, 100% { opacity: 0.46; transform: scale(1); }
  48% { opacity: 1; transform: scale(1.12); }
}

@keyframes brandWordScan {
  0%, 22% { stroke-dashoffset: 180; opacity: 0; }
  40% { opacity: 0.42; }
  72%, 100% { stroke-dashoffset: -110; opacity: 0; }
}

@keyframes brandWordOrbit {
  to { stroke-dashoffset: -24; }
}

@keyframes brandAccentGlow {
  0%, 100% { opacity: 0.96; }
  50% { opacity: 1; filter: drop-shadow(0 0 8px rgba(47, 225, 195, 0.3)); }
}

@keyframes brandDotTraverse {
  0% { transform: rotate(0deg) translateX(12px) rotate(0deg) scale(0.85); z-index: 3; opacity: 0.75; filter: blur(0.3px); }
  25% { transform: rotate(90deg) translateX(12px) rotate(-90deg) scale(1); z-index: 6; opacity: 1; filter: blur(0px); }
  50% { transform: rotate(180deg) translateX(12px) rotate(-180deg) scale(1.15); z-index: 6; opacity: 1; filter: blur(0px); }
  75% { transform: rotate(270deg) translateX(12px) rotate(-270deg) scale(1); z-index: 3; opacity: 0.85; filter: blur(0.3px); }
  100% { transform: rotate(360deg) translateX(12px) rotate(-360deg) scale(0.85); z-index: 3; opacity: 0.75; filter: blur(0.3px); }
}

@keyframes brandNPulse {
  0%, 100% {
    fill: currentColor;
    filter: drop-shadow(0 0 1px rgba(103, 232, 249, 0.1));
  }
  50% {
    fill: #f8fafc;
    filter: drop-shadow(0 0 5px rgba(103, 232, 249, 0.45));
  }
}

@keyframes brandIPulse {
  0%, 100% {
    fill: var(--brand-accent, #2FE1C3);
    filter: drop-shadow(0 0 1px rgba(47, 225, 195, 0.1));
  }
  50% {
    fill: #5eead4;
    filter: drop-shadow(0 0 8px rgba(47, 225, 195, 0.75));
  }
}

@keyframes brandNStrokePulse {
  0%, 100% { stroke: rgba(255,255,255,0.18); }
  50% { stroke: rgba(34, 211, 238, 0.5); }
}

@keyframes brandIStrokePulse {
  0%, 100% { stroke: rgba(255,255,255,0.22); }
  50% { stroke: rgba(47, 225, 195, 0.55); }
}

@keyframes brandDotPulse {
  0%, 100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 var(--brand-dot-glow);
  }
  50% {
    transform: scale(1.08);
    box-shadow: 0 0 0 10px rgba(47, 225, 195, 0);
  }
}

@keyframes brandWordmarkPulse {
  0%, 100% { transform: translateY(0); opacity: .98; }
  50% { transform: translateY(var(--brand-wordmark-pulse-up)); opacity: 1; }
}

@keyframes brandWordmarkFloat {
  0%, 100% { transform: translateY(0); }
  35% { transform: translateY(var(--brand-wordmark-float-up)); }
  70% { transform: translateY(var(--brand-wordmark-float-down)); }
}

@media (prefers-reduced-motion: reduce) {
  .brand-dot__core,
  .brand-i-head-orbit,
  .brand-i-head--travel,
  .brand-i-stem-origin,
  .brand-mark,
  .brand-mark__scan,
  .brand-wordmark-orbit,
  .brand-wordmark-scanline,
  .brand-wordmark-text--accent,
