/* Premium traceability globe shared by SDK, landing, Demo Lab and investor pages. */
.traceability-globe {
  position: relative;
  isolation: isolate;
  display: grid;
  min-height: 560px;
  overflow: hidden;
  border: 1px solid rgba(103, 232, 249, 0.18);
  border-radius: 32px;
  background:
    radial-gradient(circle at 22% 18%, rgba(34, 211, 238, 0.18), transparent 18rem),
    radial-gradient(circle at 78% 18%, rgba(245, 158, 11, 0.12), transparent 17rem),
    linear-gradient(145deg, rgba(2, 6, 23, 0.96), rgba(4, 19, 31, 0.94) 54%, rgba(2, 6, 23, 0.98));
  box-shadow: 0 38px 110px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.traceability-globe::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image:
    linear-gradient(rgba(125, 211, 252, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(125, 211, 252, 0.055) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: radial-gradient(circle at 58% 48%, #000 0%, transparent 74%);
}

.traceability-globe__header,
.traceability-globe__footer {
  position: relative;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.25rem 0;
}

.traceability-globe__header p {
  color: #67e8f9;
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.traceability-globe__header h2 {
  margin-top: 0.35rem;
  color: #f8fafc;
  font-size: clamp(1.15rem, 1.8vw, 1.75rem);
  font-weight: 950;
  line-height: 1.12;
}

.traceability-globe__header span,
.traceability-globe__footer p {
  display: block;
  max-width: 34rem;
  margin-top: 0.45rem;
  color: #94a3b8;
  font-size: 0.8rem;
  font-weight: 650;
  line-height: 1.55;
}

.traceability-globe__kpis {
  display: flex;
  gap: 0.55rem;
}

.traceability-globe__kpis strong {
  min-width: 5.25rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  background: rgba(15, 23, 42, 0.72);
  padding: 0.68rem 0.78rem;
  color: #f8fafc;
  font-size: 1rem;
  font-weight: 950;
  text-align: right;
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.24);
  backdrop-filter: blur(16px);
}

.traceability-globe__kpis small {
  display: block;
  margin-top: 0.18rem;
  color: #67e8f9;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.traceability-globe__stage {
  position: relative;
  min-height: 390px;
  margin: 0.25rem 1rem;
}

.traceability-globe__routebar {
  position: absolute;
  left: clamp(0.9rem, 2vw, 1.35rem);
  right: clamp(0.9rem, 2vw, 1.35rem);
  bottom: clamp(0.9rem, 2vw, 1.35rem);
  z-index: 18;
  max-width: 28rem;
  border: 1px solid rgba(103, 232, 249, 0.18);
  border-radius: 20px;
  background: linear-gradient(135deg, rgba(2, 6, 23, 0.84), rgba(8, 47, 73, 0.68));
  padding: 0.78rem 0.9rem;
  color: #e0f2fe;
  box-shadow: 0 22px 58px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  pointer-events: none;
  backdrop-filter: blur(18px);
}

.traceability-globe__routebar span,
.traceability-globe__routebar small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.traceability-globe__routebar span {
  color: #67e8f9;
  font-size: 0.58rem;
  font-weight: 950;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.traceability-globe__routebar strong {
  display: block;
  margin-top: 0.18rem;
  overflow: hidden;
  color: #f8fafc;
  font-size: clamp(0.95rem, 1.4vw, 1.2rem);
  font-weight: 950;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.traceability-globe__routebar small {
  margin-top: 0.28rem;
  color: #94a3b8;
  font-size: 0.72rem;
  font-weight: 750;
}

.traceability-globe__orb {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(76%, 560px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%) rotateX(58deg) rotateZ(-14deg);
  transform-style: preserve-3d;
  border: 1px solid rgba(103, 232, 249, 0.2);
  border-radius: 999px;
  background: radial-gradient(circle at 45% 34%, rgba(34, 211, 238, 0.26), rgba(2, 6, 23, 0.9) 67%);
  box-shadow:
    0 0 0 1px rgba(34, 211, 238, 0.08),
    0 0 70px rgba(34, 211, 238, 0.2),
    inset 0 0 60px rgba(103, 232, 249, 0.1);
}

.traceability-globe__orb svg {
  position: absolute;
  inset: 4%;
  overflow: visible;
  transform: rotateZ(14deg);
  filter: drop-shadow(0 0 22px rgba(34, 211, 238, 0.18));
}

.traceability-globe__halo {
  position: absolute;
  inset: 4%;
  border: 1px solid rgba(103, 232, 249, 0.18);
  border-radius: 999px;
  animation: traceabilityGlobeSpin 26s linear infinite;
}

.traceability-globe__halo--two {
  inset: 13%;
  border-color: rgba(167, 139, 250, 0.16);
  animation-duration: 19s;
  animation-direction: reverse;
}

.traceability-globe__halo--three {
  inset: 24%;
  border-color: rgba(52, 211, 153, 0.16);
  animation-duration: 15s;
}

.traceability-globe__core {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 4;
  display: grid;
  width: 118px;
  height: 118px;
  place-items: center;
  transform: translate(-50%, -50%) rotateZ(14deg) rotateX(-58deg);
  border: 1px solid rgba(103, 232, 249, 0.56);
  border-radius: 24px;
  background:
    radial-gradient(circle at 50% 24%, rgba(103, 232, 249, 0.36), transparent 44%),
    linear-gradient(145deg, rgba(15, 23, 42, 0.94), rgba(2, 6, 23, 0.96));
  box-shadow: 0 0 46px rgba(34, 211, 238, 0.28), inset 0 -10px 24px rgba(34, 211, 238, 0.16);
}

.traceability-globe__core i,
.traceability-globe__core b {
  grid-column: 1;
  grid-row: 1;
  font-style: normal;
}

.traceability-globe__core i {
  transform: translateY(-8px);
  color: #ecfeff;
  font-size: 1.2rem;
  font-weight: 950;
}

.traceability-globe__core b {
  transform: translateY(18px);
  color: #67e8f9;
  font-size: 0.62rem;
  letter-spacing: 0.2em;
}

.traceability-globe__land {
  fill: rgba(34, 211, 238, 0.22);
  stroke: rgba(103, 232, 249, 0.28);
  stroke-width: 0.35;
}

.traceability-globe__land--americas {
  fill: rgba(52, 211, 153, 0.24);
}

.traceability-globe__land--emea {
  fill: rgba(34, 211, 238, 0.2);
}

.traceability-globe__land--south {
  fill: rgba(167, 139, 250, 0.22);
}

.traceability-globe__grid {
  fill: none;
  stroke: rgba(148, 163, 184, 0.18);
  stroke-width: 0.28;
  stroke-dasharray: 1.5 2.2;
}

.traceability-globe__route {
  fill: none;
  stroke: url("#traceability-globe-route");
  stroke-width: 0.82;
  stroke-linecap: round;
  stroke-dasharray: 4 5;
  filter: drop-shadow(0 0 6px rgba(34, 211, 238, 0.72));
  animation: traceabilityRouteFlow 2.8s linear infinite;
}

.traceability-globe__route.is-warn {
  stroke: url("#traceability-globe-route-warn");
