.sun-product-visual::before {
  content: "";
  position: absolute;
  left: 1.25rem;
  top: -1.45rem;
  width: 1.9rem;
  height: 2rem;
  border-radius: 0.45rem 0.45rem 0.25rem 0.25rem;
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.13) 0 4px, transparent 4px 9px),
    linear-gradient(180deg, #dc2626 0%, #7f1d1d 100%);
  border: 1px solid rgba(254, 202, 202, 0.72);
  transition: transform 0.45s ease, opacity 0.45s ease;
}

.sun-product-visual::after {
  content: "";
  position: absolute;
  inset: 3.4rem 0.45rem 1.45rem;
  border-radius: 0.35rem;
  background:
    linear-gradient(105deg, transparent 0 43%, rgba(251, 113, 133, 0.0) 44% 54%, transparent 55%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.55), transparent 30%),
    linear-gradient(180deg, rgba(226, 232, 240, 0.95), rgba(203, 213, 225, 0.9));
  border: 1px solid rgba(103, 232, 249, 0.3);
  box-shadow: 0 10px 20px rgba(2, 6, 23, 0.28);
}

.sun-product-visual--valid {
  box-shadow:
    inset 0 0 24px rgba(2, 6, 23, 0.84),
    0 18px 32px rgba(0, 0, 0, 0.38),
    0 0 32px rgba(52, 211, 153, 0.18);
}

.sun-product-visual--valid::before {
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.16) 0 4px, transparent 4px 9px),
    linear-gradient(180deg, #22d3ee 0%, #059669 100%);
  border-color: rgba(110, 231, 183, 0.76);
}

.sun-product-visual--valid::after {
  border-color: rgba(52, 211, 153, 0.44);
}

.sun-product-visual--warn {
  box-shadow:
    inset 0 0 24px rgba(2, 6, 23, 0.84),
    0 18px 32px rgba(0, 0, 0, 0.38),
    0 0 32px rgba(251, 191, 36, 0.18);
}

.sun-product-visual--warn::before {
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.16) 0 4px, transparent 4px 9px),
    linear-gradient(180deg, #fbbf24 0%, #b45309 100%);
  border-color: rgba(253, 230, 138, 0.76);
}

.sun-product-visual--risk {
  box-shadow:
    inset 0 0 24px rgba(2, 6, 23, 0.84),
    0 18px 32px rgba(0, 0, 0, 0.38),
    0 0 34px rgba(251, 113, 133, 0.22);
}

.sun-product-visual--risk::before {
  background:
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.13) 0 4px, transparent 4px 9px),
    linear-gradient(180deg, #fb7185 0%, #7f1d1d 100%);
  border-color: rgba(254, 202, 202, 0.72);
}

.sun-product-visual--risk::after {
  border-color: rgba(251, 113, 133, 0.56);
  background:
    linear-gradient(110deg, transparent 0 47%, rgba(251, 113, 133, 0.72) 48% 52%, transparent 53%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.55), transparent 30%),
    linear-gradient(180deg, rgba(226, 232, 240, 0.95), rgba(203, 213, 225, 0.9));
}

.sun-product-visual--replay {
  box-shadow:
    inset 0 0 24px rgba(2, 6, 23, 0.9),
    0 18px 32px rgba(0, 0, 0, 0.42),
    0 0 38px rgba(251, 191, 36, 0.26);
}

.sun-product-visual--replay::after {
  border-color: rgba(251, 191, 36, 0.48);
  background:
    linear-gradient(110deg, transparent 0 42%, rgba(251, 191, 36, 0.68) 43% 48%, transparent 49%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.55), transparent 30%),
    linear-gradient(180deg, rgba(226, 232, 240, 0.95), rgba(203, 213, 225, 0.9));
}

.sun-product-visual--opened::before {
  transform: translate(-0.45rem, -0.75rem) rotate(-24deg);
  opacity: 0.78;
}

.sun-product-visual--opened::after {
  border-color: rgba(251, 191, 36, 0.52);
  background:
    linear-gradient(110deg, transparent 0 47%, rgba(251, 191, 36, 0.72) 48% 52%, transparent 53%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.55), transparent 30%),
    linear-gradient(180deg, rgba(226, 232, 240, 0.95), rgba(203, 213, 225, 0.9));
}

.sun-product-visual--opened .sun-product-visual__tag {
  border-color: rgba(251, 191, 36, 0.55);
  box-shadow: 0 0 18px rgba(251, 191, 36, 0.22);
}

.sun-product-visual__tag {
  position: absolute;
  z-index: 1;
  left: 50%;
  bottom: 1.45rem;
  transform: translateX(-50%);
  border-radius: 999px;
  background: rgba(248, 250, 252, 0.9);
  border: 1px solid rgba(15, 23, 42, 0.22);
