}

.sun-status-dot--good { background: #34d399; }
.sun-status-dot--warn { background: #fbbf24; }
.sun-status-dot--risk { background: #fb7185; }
.sun-status-dot--replay { background: #f59e0b; }

.sun-security-steps {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
