}

.sun-security-step span {
  display: inline-grid;
  place-items: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 999px;
  background: rgba(34, 211, 238, 0.12);
  color: #67e8f9;
  font-size: 0.62rem;
  font-weight: 900;
}

.sun-security-step b {
  display: block;
  margin-top: 0.45rem;
  color: #f8fafc;
  font-size: 0.74rem;
}

.sun-security-step p {
  margin-top: 0.2rem;
  color: #94a3b8;
  font-size: 0.68rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.sun-security-footer {
  display: grid;
  gap: 0.45rem;
  margin-top: 0.9rem;
}

.sun-security-footer span {
  border: 1px solid rgba(125, 211, 252, 0.14);
  border-radius: 0.9rem;
  background: rgba(15, 23, 42, 0.58);
  color: #bae6fd;
  font-size: 0.68rem;
  line-height: 1.35;
  padding: 0.55rem 0.7rem;
