}

.sun-public-cta-card {
  color: #e0f2fe !important;
  background:
    linear-gradient(135deg, rgba(14, 165, 233, 0.14), rgba(15, 23, 42, 0.68)) !important;
  border-color: rgba(125, 211, 252, 0.22) !important;
