}

.sun-topbar-actions {
  flex: 0 0 auto;
}

.sun-topbar .theme-toggle {
  min-height: 2rem;
  border-color: rgba(125, 211, 252, 0.22);
  background: rgba(15, 23, 42, 0.78);
  padding: 0.42rem 0.62rem;
  color: #e0f2fe;
  box-shadow: 0 12px 28px rgba(2, 6, 23, 0.18);
}

.sun-topbar .theme-toggle__glyph {
  flex: 0 0 auto;
}

.sun-live-tap-pill {
  min-height: 2rem;
  white-space: nowrap;
}

.sun-quick-nav {
  position: sticky;
  top: calc(max(0.5rem, env(safe-area-inset-top)) + 4.2rem);
  z-index: 32;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  border-radius: 1rem;
}

/* Landing premium vertical showcase: global platform signal, not a single-industry demo. */
.landing-premium-verticals {
  position: relative;
}

.landing-premium-verticals::before {
  content: "";
  position: absolute;
  inset: 2rem 0 auto;
  height: 34rem;
  pointer-events: none;
  background:
    radial-gradient(circle at 20% 18%, rgba(34, 211, 238, 0.15), transparent 34%),
    radial-gradient(circle at 86% 24%, rgba(245, 158, 11, 0.1), transparent 30%);
  filter: blur(2px);
}

.landing-premium-verticals__head,
.landing-premium-verticals__grid {
  position: relative;
  z-index: 1;
}

.landing-premium-verticals__head {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(360px, 0.62fr);
  gap: clamp(1.5rem, 4vw, 4rem);
  align-items: end;
  margin-bottom: 1.2rem;
}

.landing-premium-verticals__head p {
  color: #22d3ee;
  font-size: 0.76rem;
  font-weight: 950;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.landing-premium-verticals__head h2 {
  max-width: 920px;
  margin-top: 0.85rem;
  color: #f8fafc;
  font-size: clamp(2rem, 4vw, 4.4rem);
  font-weight: 950;
  line-height: 1.02;
}

.landing-premium-verticals__head span {
  display: block;
  color: #cbd5e1;
  font-size: 0.96rem;
  line-height: 1.75;
}

.landing-premium-verticals__head div:last-child > div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-top: 1rem;
}

.landing-premium-verticals__head a {
  display: inline-flex;
  min-height: 2.65rem;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(103, 232, 249, 0.35);
  border-radius: 999px;
  background: rgba(34, 211, 238, 0.1);
  padding: 0.62rem 1rem;
  color: #cffafe;
  font-size: 0.85rem;
  font-weight: 900;
}

.landing-premium-verticals__head a:first-child {
  background: linear-gradient(135deg, #22d3ee, #2dd4bf);
  color: #02131d;
  box-shadow: 0 18px 42px rgba(34, 211, 238, 0.2);
}

.landing-premium-verticals__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.landing-premium-vertical-card {
  position: relative;
  display: block;
  min-height: 360px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 24px;
  background: rgba(15, 23, 42, 0.82);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.25);
  isolation: isolate;
  text-decoration: none;
}

.landing-premium-vertical-card::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(180deg, transparent 12%, rgba(2, 6, 23, 0.16) 46%, rgba(2, 6, 23, 0.92) 100%),
    linear-gradient(135deg, rgba(34, 211, 238, 0.08), transparent 42%);
}

.landing-premium-vertical-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 520ms ease;
}

.landing-premium-vertical-card:hover img {
  transform: scale(1.055);
}

.landing-premium-vertical-card__body {
  position: absolute;
  inset: auto 0 0;
  z-index: 2;
  padding: 1.2rem;
}

.landing-premium-vertical-card__body h3 {
  color: #f8fafc;
  font-size: 1.25rem;
  font-weight: 950;
  line-height: 1.15;
}

.landing-premium-vertical-card__body p {
  max-width: 26rem;
  margin-top: 0.55rem;
  color: #dbeafe;
  font-size: 0.86rem;
  font-weight: 650;
  line-height: 1.55;
}

.landing-premium-vertical-card__body div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.42rem;
  margin-top: 0.85rem;
}

.landing-premium-vertical-card__body span {
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  background: rgba(2, 6, 23, 0.68);
  padding: 0.28rem 0.52rem;
  color: #e0f2fe;
  font-size: 0.63rem;
  font-weight: 950;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
}

@media (max-width: 1180px) {
  .landing-premium-verticals__head {
    grid-template-columns: 1fr;
  }

  .landing-premium-verticals__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .landing-premium-verticals__grid {
    grid-template-columns: 1fr;
  }

  .landing-premium-vertical-card {
    min-height: 330px;
  }

  .landing-premium-vertical-card__body {
    padding: 1rem;
  }
}

/* SDK page: premium multi-industry command center. */
.sdk-page-shell {
