.sdk-global-hero-scene {
  position: relative;
  min-height: 610px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 32px;
  background:
    radial-gradient(circle at 48% 48%, rgba(34, 211, 238, 0.18), transparent 25%),
    radial-gradient(circle at 73% 28%, rgba(245, 158, 11, 0.12), transparent 24%),
    linear-gradient(135deg, rgba(4, 11, 20, 0.98), rgba(5, 22, 32, 0.94) 58%, rgba(2, 6, 23, 0.98));
  box-shadow: 0 36px 120px rgba(0, 0, 0, 0.52), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.sdk-global-hero-scene::before {
  content: "";
  position: absolute;
  inset: 8% 2% 10%;
  background-image:
    radial-gradient(circle, rgba(103, 232, 249, 0.5) 1px, transparent 1.35px),
    radial-gradient(circle, rgba(245, 158, 11, 0.46) 1px, transparent 1.35px);
  background-position: 0 0, 7px 5px;
  background-size: 16px 11px, 29px 19px;
  mask-image: radial-gradient(ellipse at center, #000 0%, #000 46%, transparent 78%);
  opacity: 0.48;
}

.sdk-world-grid,
.sdk-world-map,
.sdk-route,
.sdk-core,
.sdk-node,
.sdk-live-card {
  position: absolute;
}

.sdk-world-grid {
  inset: 0;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.075) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.075) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.86), transparent 92%);
}

.sdk-world-map {
  inset: 8% 4% 7%;
  border-radius: 32px;
  background:
    radial-gradient(ellipse at 18% 45%, rgba(52, 211, 153, 0.2) 0%, rgba(52, 211, 153, 0.12) 13%, transparent 14%),
    radial-gradient(ellipse at 46% 38%, rgba(34, 211, 238, 0.2) 0%, rgba(34, 211, 238, 0.12) 11%, transparent 12%),
    radial-gradient(ellipse at 70% 32%, rgba(251, 191, 36, 0.18) 0%, rgba(251, 191, 36, 0.1) 12%, transparent 13%),
    radial-gradient(ellipse at 77% 61%, rgba(167, 139, 250, 0.17) 0%, rgba(167, 139, 250, 0.08) 9%, transparent 10%);
}

.sdk-world-map::before {
  content: "";
  position: absolute;
  inset: 11% 7%;
  border-top: 1px dashed rgba(148, 163, 184, 0.18);
  border-bottom: 1px dashed rgba(148, 163, 184, 0.14);
  transform: skewY(-8deg);
}

.sdk-world-map::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(110deg, transparent 30%, rgba(34, 211, 238, 0.12) 49%, transparent 67%),
    linear-gradient(20deg, transparent 38%, rgba(52, 211, 153, 0.11) 49%, transparent 62%);
  opacity: 0.82;
}

.sdk-route {
  height: 2px;
  transform-origin: left center;
  background: linear-gradient(90deg, transparent, rgba(103, 232, 249, 0.95), rgba(52, 211, 153, 0.74), transparent);
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.45);
  animation: sdkRouteFlow 3.4s linear infinite;
}

.sdk-route--one {
  left: 33%;
  top: 36%;
  width: 37%;
  transform: rotate(11deg);
}

.sdk-route--two {
  left: 29%;
  top: 62%;
  width: 39%;
  transform: rotate(-16deg);
  animation-delay: -1.2s;
}

.sdk-route--three {
  left: 47%;
  top: 47%;
  width: 30%;
  transform: rotate(36deg);
  animation-delay: -2s;
}

.sdk-core {
  left: 53%;
  top: 48%;
  z-index: 5;
  display: grid;
  width: 150px;
  height: 150px;
  place-items: center;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(103, 232, 249, 0.6);
  border-radius: 26px;
  background:
    radial-gradient(circle at 50% 36%, rgba(34, 211, 238, 0.36), rgba(15, 23, 42, 0.95) 68%),
    rgba(2, 6, 23, 0.92);
  box-shadow: 0 0 48px rgba(34, 211, 238, 0.3), inset 0 -12px 24px rgba(34, 211, 238, 0.16);
  animation: sdkCorePulse 3.8s ease-in-out infinite;
}

.sdk-core::after {
  content: "";
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(103, 232, 249, 0.2);
  border-radius: 20px;
}

.sdk-core span,
.sdk-core strong {
