  grid-row: 1;
}

.sdk-core span {
  transform: translateY(-10px);
  color: #ecfeff;
  font-size: 1.55rem;
  font-weight: 950;
}

.sdk-core strong {
  transform: translateY(22px);
  color: #67e8f9;
  font-size: 0.72rem;
  font-weight: 950;
  letter-spacing: 0.2em;
}

.sdk-node {
  z-index: 6;
