}

@keyframes sdkRouteFlow {
  0% { opacity: 0.25; background-position: -120px 0; }
  50% { opacity: 1; }
  100% { opacity: 0.25; background-position: 120px 0; }
}

@keyframes sdkCorePulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); }
  50% { transform: translate(-50%, -50%) scale(1.035); }
}

@media (max-width: 1380px) {
  .sdk-premium-hero {
    grid-template-columns: minmax(0, 0.9fr) minmax(520px, 1.1fr);
