    display: none;
  }

  .sdk-premium-hero {
    width: 100%;
    min-width: 0;
    grid-template-columns: minmax(0, 1fr);
    gap: 2rem;
  }

  .sdk-premium-copy {
    min-width: 0;
    max-width: 100%;
  }

  .sdk-premium-copy h1 {
    max-width: min(20.5rem, calc(100vw - 2rem));
    font-size: clamp(1.72rem, 7.2vw, 2.02rem);
    line-height: 1.12;
    overflow-wrap: break-word;
    text-wrap: balance;
  }

  .sdk-premium-copy h1 br {
    display: none;
  }

  .sdk-premium-copy > p:not(.sdk-hero-eyebrow) {
    max-width: min(21rem, calc(100vw - 2rem));
    font-size: 0.92rem;
    line-height: 1.65;
    overflow-wrap: anywhere;
  }

  .sdk-hero-actions {
    flex-direction: column;
  }

  .sdk-hero-actions a,
  .sdk-hero-actions button {
    width: 100%;
    min-width: 0;
    white-space: normal;
  }

  .sdk-hero-eyebrow {
    font-size: 0.64rem;
    letter-spacing: 0.22em;
  }

  .sdk-trust-rail,
  .sdk-industry-showcase {
    grid-template-columns: 1fr;
  }

  .sdk-trust-rail div {
    min-height: auto;
    border-right: 0;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    padding-bottom: 0.85rem;
  }

  .sdk-global-hero-scene {
    min-height: 690px;
    border-radius: 22px;
  }

  .sdk-live-card--left {
    left: 14px;
    top: 14px;
    width: 176px;
  }

  .sdk-live-card--right {
    right: 14px;
    top: 132px;
    width: 166px;
  }

  .sdk-live-card--device {
    right: 14px;
    bottom: 20px;
    width: 176px;
  }

  .sdk-core {
    top: 48%;
    width: 116px;
    height: 116px;
    border-radius: 22px;
  }

  .sdk-core span {
    font-size: 1.15rem;
  }

  .sdk-node {
    min-width: 96px;
    padding: 8px;
  }

  .sdk-node:nth-of-type(6),
  .sdk-node:nth-of-type(7) {
    display: none;
  }

  .sdk-industry-card {
    grid-template-columns: 1fr;
  }

  .sdk-industry-image,
  .sdk-industry-image-wrap {
    min-height: 220px;
  }

  .sdk-trusted-rail {
    justify-content: flex-start;
  }

  .sdk-trusted-rail strong {
    border-left: 0;
    padding-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sdk-route,
  .sdk-core,
  .sdk-industry-image {
    animation: none;
    transition: none;
  }
}

