@keyframes sunTapWave {
  0% { opacity: 0.8; transform: scale(0.7); }
  100% { opacity: 0; transform: scale(1.45); }
}

@keyframes sunStatusPulse {
  0% { box-shadow: 0 0 0 0 rgba(34, 211, 238, 0.35); }
  70% { box-shadow: 0 0 0 0.75rem rgba(34, 211, 238, 0); }
  100% { box-shadow: 0 0 0 0 rgba(34, 211, 238, 0); }
}

@keyframes sunBottleFloat {
  0%, 100% { transform: translateY(0) rotate(-1deg); }
  50% { transform: translateY(-0.4rem) rotate(1.5deg); }
}

@keyframes sunRouteFlow {
  0% { opacity: 0.28; background-position: 0 0; }
  50% { opacity: 0.9; }
  100% { opacity: 0.28; background-position: 40px 0; }
}

@keyframes sunLogoOrbit {
  to { transform: rotate(360deg); }
}

@media (min-width: 1024px) {
  .sun-mobile-surface {
    padding-left: clamp(1.5rem, 3vw, 3rem);
    padding-right: clamp(1.5rem, 3vw, 3rem);
  }

  .sun-mobile-shell {
    display: grid;
    width: min(100%, 1480px);
    max-width: min(1480px, calc(100vw - 3rem));
    grid-template-columns: minmax(390px, 500px) minmax(0, 1fr);
    gap: 1.25rem;
    align-items: start;
  }

  .sun-mobile-shell > :not([hidden]) ~ :not([hidden]) {
    margin-top: 0;
  }

  .sun-topbar,
  .sun-quick-nav {
    grid-column: 1 / -1;
  }

  .sun-topbar {
    top: 1rem;
    padding: 0.72rem 0.82rem;
  }

  .sun-quick-nav {
    position: static;
    display: flex;
    justify-content: flex-end;
    gap: 0.6rem;
  }

  .sun-quick-nav a {
    min-width: 9.5rem;
    max-width: 13rem;
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .sun-passport-hero {
    grid-column: 1;
    grid-row: 3 / span 7;
    position: sticky;
    top: 6.4rem;
  }

  .sun-product-stage {
    width: 100%;
    height: clamp(18rem, 30vw, 28rem);
  }

  .sun-product-visual {
    width: clamp(6rem, 8vw, 7.6rem);
    height: clamp(9rem, 12vw, 11.8rem);
  }

  .sun-security-ledger {
    padding: clamp(1rem, 1.6vw, 1.35rem);
  }

  .sun-security-steps {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .sun-config-panel,
  .sun-certificate-panel,
  .sun-journey-panel,
  .sun-priority-panel,
  .sun-actions-panel,
  .sun-map-section,
  .sun-loyalty-panel,
  .sun-passport-banner,
  .sun-posttap-panel,
  .sun-tech-panel,
  .sun-cta-actions,
  .sun-onboard-action {
    grid-column: 2;
  }

  .sun-panel-map {
    grid-column: 1 / -1;
  }

  .sun-map-section--enterprise {
    padding: 1rem !important;
  }

  .sun-config-panel .grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .sun-map-section--enterprise .global-ops-map-layout {
    grid-template-columns: minmax(0, 1fr) minmax(20rem, 24rem) !important;
  }

  .sun-map-section--enterprise .global-ops-map-canvas {
    height: clamp(30rem, 58vh, 42rem) !important;
  }

  .sun-map-section--enterprise .global-ops-map-drawer {
    height: clamp(30rem, 58vh, 42rem) !important;
    max-height: none;
  }
}

@media (min-width: 1280px) {
  .sun-mobile-shell {
    grid-template-columns: minmax(420px, 520px) minmax(0, 1fr);
    gap: 1.5rem;
  }

  .sun-panel-primary {
    min-height: 0;
  }

  .sun-panel-journey,
  .sun-panel-priority,
  .sun-panel-actions {
    align-self: stretch;
  }
}

/* Premium post-tap visual pass: the mobile/API passport must sell the same
   physical-product story as Demo Lab, but in a compact consumer view. */
.sun-product-stage {
  isolation: isolate;
  perspective: 900px;
  width: min(100%, 24rem);
  height: clamp(21rem, 68vw, 26rem);
  background:
    linear-gradient(90deg, rgba(125, 211, 252, 0.055) 1px, transparent 1px),
    linear-gradient(rgba(125, 211, 252, 0.055) 1px, transparent 1px),
    radial-gradient(ellipse at 50% 92%, rgba(45, 212, 191, 0.14), transparent 34%),
    linear-gradient(150deg, rgba(8, 47, 73, 0.72), rgba(2, 6, 23, 0.92) 62%, rgba(15, 23, 42, 0.88));
  background-size: 4rem 4rem, 4rem 4rem, auto, auto;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 -3.4rem 6.4rem rgba(2, 6, 23, 0.48),
    0 1.6rem 4.4rem rgba(2, 6, 23, 0.32);
}

.sun-product-stage::before {
  inset: 8%;
  border: 1px solid rgba(125, 211, 252, 0.12);
  background:
    repeating-radial-gradient(ellipse at center, rgba(125, 211, 252, 0.12) 0 1px, transparent 1px 20px);
  opacity: 0.34;
  transform: rotateX(64deg) translateY(38%);
}

.sun-product-stage::after {
  left: 10%;
  right: 10%;
  top: 13%;
  height: 68%;
  border-top: 0;
  border-radius: 999px;
  background:
    conic-gradient(from 218deg at 45% 55%, transparent 0 20%, rgba(103, 232, 249, 0.09) 21% 29%, transparent 30% 100%);
  transform: rotate(-8deg);
  animation: sunRouteFlow 4.2s linear infinite;
}

.sun-stage-map {
  position: absolute;
  inset: 0.9rem;
  z-index: 0;
  border-radius: 1.5rem;
  overflow: hidden;
  pointer-events: none;
}

.sun-stage-real-map {
  position: absolute;
  inset: 0.75rem;
  z-index: 0;
  border-radius: 1.35rem;
  overflow: hidden;
  pointer-events: none;
  background: #020617;
  box-shadow:
    inset 0 0 0 1px rgba(125, 211, 252, 0.14),
    inset 0 -4.5rem 6rem rgba(2, 6, 23, 0.38);
}

.sun-stage-real-map,
.sun-map-section--enterprise .global-ops-map-stage {
  --nexid-ops-fallback-fill: rgba(8, 28, 42, 0.22);
  --nexid-ops-fallback-ring: rgba(148, 163, 184, 0.12);
  --nexid-ops-fallback-ring-accent: rgba(34, 211, 238, 0.18);
  --nexid-ops-route-shadow: rgba(2, 6, 23, 0.58);
  --nexid-ops-label-fill: rgba(226, 232, 240, 0.92);
  --nexid-ops-heat-good: rgba(34, 211, 238, 0.42);
  --nexid-ops-heat-risk: rgba(251, 113, 133, 0.5);
}

.sun-stage-real-map::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(2, 6, 23, 0.01), rgba(2, 6, 23, 0.12)),
    radial-gradient(circle at 50% 48%, transparent 0 58%, rgba(2, 6, 23, 0.18) 84%);
  pointer-events: none;
}

.sun-stage-real-map__vector {
  height: 100%;
  border: 0 !important;
  border-radius: inherit !important;
  background: transparent !important;
  box-shadow: none !important;
}

.sun-stage-real-map__vector svg {
  opacity: 0.98;
  filter: saturate(1.12) contrast(1.04) brightness(1.04);
}

.sun-stage-map::before,
.sun-stage-map::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.sun-stage-map::before {
  background:
    linear-gradient(90deg, rgba(125, 211, 252, 0.07) 1px, transparent 1px),
    linear-gradient(rgba(125, 211, 252, 0.07) 1px, transparent 1px);
  background-size: 3.4rem 3.4rem;
  mask-image: radial-gradient(circle at center, black, transparent 78%);
}

.sun-stage-map::after {
  background:
    radial-gradient(circle at 24% 63%, rgba(52, 211, 153, 0.16), transparent 9%),
    radial-gradient(circle at 73% 36%, rgba(34, 211, 238, 0.14), transparent 10%);
  filter: blur(5px);
  opacity: 0.44;
}

.sun-stage-map__land {
  position: absolute;
  display: block;
  border: 1px dashed rgba(125, 211, 252, 0.15);
  background: transparent;
  opacity: 0.18;
  filter: none;
}

.sun-stage-map__land--origin {
  left: 6%;
  bottom: 17%;
  width: 38%;
  height: 31%;
  border-radius: 56% 44% 42% 58% / 44% 42% 58% 56%;
  transform: rotate(-12deg);
}

.sun-stage-map__land--tap {
  right: 4%;
  top: 19%;
  width: 40%;
  height: 35%;
  border-radius: 45% 55% 59% 41% / 42% 50% 50% 58%;
  background: transparent;
  transform: rotate(13deg);
}

.sun-stage-map__route,
.sun-stage-map__route--glow {
  position: absolute;
  left: 18%;
  right: 15%;
  top: 49%;
  height: 34%;
  border-top: 2px dashed rgba(103, 232, 249, 0.58);
  border-radius: 999px 999px 0 0;
  transform: rotate(-13deg);
}

.sun-stage-map__route--glow {
  border-top-width: 5px;
  border-color: rgba(34, 211, 238, 0.09);
  filter: blur(4px);
}

.sun-stage-map__point {
  position: absolute;
  z-index: 2;
  display: block;
  width: 0.92rem;
  height: 0.92rem;
  border: 2px solid rgba(236, 254, 255, 0.88);
  border-radius: 999px;
  background: #22d3ee;
  box-shadow: 0 0 0 0.34rem rgba(34, 211, 238, 0.18), 0 0 1.4rem rgba(34, 211, 238, 0.58);
}

.sun-stage-map__point--origin {
  left: 21%;
  bottom: 29%;
  background: #34d399;
}

.sun-stage-map__point--tap {
  right: 20%;
  top: 40%;
  background: #22d3ee;
  animation: sunStatusPulse 2.4s ease-out infinite;
}

.sun-product-visual {
  width: clamp(6.7rem, 24vw, 8.8rem);
  height: clamp(11.1rem, 38vw, 14.8rem);
  z-index: 2;
  border: 0;
  border-radius: 2.8rem 2.8rem 1.55rem 1.55rem;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.26), transparent 14%, transparent 70%, rgba(255, 255, 255, 0.1)),
    radial-gradient(circle at 49% 9%, rgba(127, 29, 29, 0.58), transparent 17%),
    linear-gradient(92deg, #06070a 0%, #26090b 16%, #5f1717 42%, #15070a 77%, #030712 100%);
  box-shadow:
    inset 0.9rem 0 1.2rem rgba(255, 255, 255, 0.06),
    inset -1.1rem 0 1.6rem rgba(2, 6, 23, 0.74),
    inset 0 0 2.6rem rgba(2, 6, 23, 0.92),
    0 2rem 2.8rem rgba(0, 0, 0, 0.42);
  clip-path: polygon(35% 0, 65% 0, 69% 23%, 87% 37%, 91% 100%, 9% 100%, 13% 37%, 31% 23%);
  transform: rotateX(2deg) rotateY(-7deg) translateY(0);
  animation: sunBottleFloat 5.2s ease-in-out infinite;
}

.sun-product-visual::before,
.sun-product-visual::after {
  content: "";
  position: absolute;
  pointer-events: none;
}

.sun-product-visual::before {
  left: 24%;
  top: 23%;
  z-index: 1;
  width: 8%;
  height: 62%;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.34), rgba(255, 255, 255, 0.04) 64%, transparent);
  border: 0 !important;
  filter: blur(0.5px);
  opacity: 0.36;
  transform: none !important;
}

.sun-product-visual::after {
  right: 19%;
  top: 28%;
  z-index: 1;
  width: 10%;
  height: 54%;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(125, 211, 252, 0.12), rgba(2, 6, 23, 0.3));
  border: 0 !important;
  opacity: 0.34;
  transform: none !important;
}

.sun-product-visual--valid::before,
.sun-product-visual--warn::before,
.sun-product-visual--risk::before,
.sun-product-visual--replay::before,
.sun-product-visual--opened::before {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.34), rgba(255, 255, 255, 0.04) 64%, transparent) !important;
}

.sun-product-visual--valid::after,
.sun-product-visual--warn::after,
.sun-product-visual--risk::after,
.sun-product-visual--replay::after,
.sun-product-visual--opened::after {
  background: linear-gradient(180deg, rgba(125, 211, 252, 0.12), rgba(2, 6, 23, 0.3)) !important;
}

.sun-product-visual__liquid,
.sun-product-visual__neck,
.sun-product-visual__capsule,
.sun-product-visual__seal,
.sun-product-visual__tag,
.sun-product-visual__label {
  position: absolute;
  display: block;
}

.sun-product-visual__liquid {
  inset: 18% 17% 3%;
  z-index: 0;
