  100% { transform: translateX(-50%) translateY(5px) rotate(-8deg) skewX(-10deg); }
}

@keyframes demoSealSpark {
  0% { transform: translate(-50%, -50%) rotate(18deg) scaleY(0.8); opacity: 0.55; }
  100% { transform: translate(-50%, -50%) rotate(18deg) scaleY(1.18); opacity: 1; }
}

@keyframes demoCorkPop {
  0% { transform: translate(-50%, 0.45rem) rotate(0deg); opacity: 0; }
  18% { transform: translate(-50%, 0) rotate(4deg); opacity: 1; }
