  0% { transform: translateY(-3px) scale(1.34) rotate(-1deg); }
  100% { transform: translateY(-13px) scale(1.41) rotate(1.6deg); }
}

@keyframes demoCorkPopPremium {
  0%, 34% { transform: translate(-50%, 0.2rem) rotate(0deg); opacity: 1; }
