/* Commercial layer: carrier profiles, marketplace network, reseller OS and unit economics. */
.landing-value-panel,
.market-network-shell {
  position: relative;
  overflow: hidden;
  box-shadow:
    0 28px 80px rgba(2, 6, 23, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.landing-value-panel::before,
.market-network-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 16% 12%, rgba(34, 211, 238, 0.16), transparent 30%),
    radial-gradient(circle at 90% 10%, rgba(139, 92, 246, 0.14), transparent 32%),
    radial-gradient(circle at 70% 84%, rgba(16, 185, 129, 0.12), transparent 28%),
    repeating-linear-gradient(0deg, rgba(125, 211, 252, 0.055) 0 1px, transparent 1px 4.8rem),
    repeating-linear-gradient(90deg, rgba(125, 211, 252, 0.045) 0 1px, transparent 1px 5.2rem);
  opacity: 0.94;
}

.landing-value-panel > *,
.market-network-shell > * {
  position: relative;
  z-index: 1;
}

.carrier-profile-card,
.market-network-node,
.white-label-step,
.unit-economics-card {
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
}

.carrier-profile-card::before,
.unit-economics-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
