.demo-lab-map-land {
  fill: transparent;
  stroke: rgba(125, 211, 252, 0.16);
  stroke-width: 1;
  stroke-dasharray: 6 14;
}

.demo-lab-map-land--tap {
  fill: transparent;
  stroke: rgba(196, 181, 253, 0.14);
