}

.demo-lab-map-ridge {
  fill: none;
  stroke: rgba(186, 230, 253, 0.18);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 8 12;
  opacity: 0.38;
}

.demo-lab-map-ridge--secondary {
  stroke: rgba(167, 139, 250, 0.18);
  opacity: 0.3;
}

.demo-lab-map-city {
  fill: #e0f2fe;
  opacity: 0.78;
  filter: drop-shadow(0 0 10px rgba(34, 211, 238, 0.64));
}

.demo-lab-route-ghost {
  fill: none;
  stroke: rgba(226, 232, 240, 0.9);
