  0%,
  28% {
    opacity: 0;
    transform: translateX(-72%);
  }

  42% {
    opacity: 1;
  }

  70%,
  100% {
    opacity: 0;
    transform: translateX(72%);
  }
}

@keyframes demo-cinematic-orbit {
  to {
    transform: rotate(360deg);
  }
}

@keyframes demo-cinematic-card-in {
  from {
    opacity: 0;
    transform: translateY(0.65rem) scale(0.96);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes demo-cinematic-bar-fill {
  from {
    opacity: 0.5;
    transform: scaleY(0.28);
    transform-origin: bottom;
  }

  to {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: bottom;
  }
}

