.demo-lab-product-scene--origin .demo-lab-nfc-seal {
  animation: demo-nfc-closed-pulse 3.6s ease-in-out infinite;
}

.demo-lab-product-scene--auth .demo-lab-nfc-seal {
  animation: demo-nfc-read-pulse 2.2s ease-in-out infinite;
}

.demo-lab-product-scene--blocked .demo-lab-nfc-seal {
  animation: demo-nfc-blocked-jolt 520ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

.demo-lab-nfc-seal-half {
  transform-box: fill-box;
  will-change: transform, opacity;
}

.demo-lab-nfc-seal-half--left {
  transform-origin: right center;
}

.demo-lab-nfc-seal-half--right {
  transform-origin: left center;
}

.demo-lab-product-scene--blocked .demo-lab-nfc-seal-half > path:first-child {
  fill: #3a0f1c;
}

.demo-lab-product-scene--open .demo-lab-nfc-seal-half--left {
  animation: demo-nfc-seal-open-left 1.25s cubic-bezier(0.16, 1, 0.3, 1) both;
