}

.demo-lab-nfc-seal-sweep {
  opacity: 0;
  transform-box: fill-box;
  will-change: transform, opacity;
}

.demo-lab-product-scene--auth .demo-lab-nfc-seal-sweep {
  animation: demo-nfc-sweep 1.65s ease-in-out infinite;
}

.demo-lab-nfc-seal-tear {
