.nexid-motion-frame {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(94, 234, 212, 0.2);
  border-radius: 1.2rem;
  background:
    radial-gradient(circle at 52% 46%, rgba(34, 211, 238, 0.2), transparent 28%),
    radial-gradient(circle at 78% 18%, rgba(167, 139, 250, 0.22), transparent 30%),
    linear-gradient(135deg, rgba(8, 47, 73, 0.92), rgba(2, 6, 23, 0.95));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04), 0 30px 70px rgba(2, 6, 23, 0.28);
  isolation: isolate;
}

.nexid-motion-frame--story {
  aspect-ratio: 9 / 16;
  max-height: 42rem;
  justify-self: center;
  width: min(100%, 26rem);
}

.nexid-motion-frame--square {
  aspect-ratio: 1 / 1;
}

.nexid-motion-frame--wide {
  aspect-ratio: 16 / 9;
}

.nexid-motion-frame-grid,
.nexid-motion-frame-scan {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.nexid-motion-frame-grid {
  z-index: 0;
  background:
    linear-gradient(rgba(125, 211, 252, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(125, 211, 252, 0.08) 1px, transparent 1px);
  background-size: 12% 12%;
}

.nexid-motion-frame-scan {
  z-index: 3;
  background: linear-gradient(110deg, transparent 0 42%, rgba(255, 255, 255, 0.12) 50%, transparent 58% 100%);
