  animation: nexid-motion-scan 4.5s ease-in-out infinite;
}

.nexid-motion-route-path {
  position: absolute;
  left: 8%;
  right: 8%;
  top: 48%;
  z-index: 1;
  height: 26%;
  transform: rotate(-8deg);
  border-top: 2px dashed rgba(94, 234, 212, 0.34);
  border-radius: 50%;
  pointer-events: none;
}

.nexid-motion-route-path span {
  position: absolute;
  display: grid;
  place-items: center;
  min-width: 4.4rem;
  border: 1px solid rgba(125, 211, 252, 0.22);
  border-radius: 999px;
  background: rgba(2, 6, 23, 0.72);
  color: #a5f3fc;
  padding: 0.34rem 0.5rem;
  font-size: 0.52rem;
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
}

.nexid-motion-route-path span:nth-child(1) {
  left: 0;
  top: 24%;
}

.nexid-motion-route-path span:nth-child(2) {
  left: 48%;
  top: -18%;
  transform: translateX(-50%);
}

.nexid-motion-route-path span:nth-child(3) {
  right: 0;
  top: 42%;
}

.nexid-motion-map-pulse {
  position: absolute;
  inset: 18% 10% 18%;
