  animation: nexid-motion-pulse 2.8s ease-out infinite;
}

.nexid-motion-map-pulse span:nth-child(1) {
  left: 8%;
  top: 66%;
}

.nexid-motion-map-pulse span:nth-child(2) {
  left: 32%;
  top: 28%;
  animation-delay: 0.35s;
}

.nexid-motion-map-pulse span:nth-child(3) {
  right: 24%;
  top: 58%;
  animation-delay: 0.7s;
}

.nexid-motion-map-pulse span:nth-child(4) {
  right: 4%;
  top: 20%;
