}

.nexid-motion-frame .nexid-motion-glyph--perfume .nexid-motion-glyph-body {
  inset: 4% 22% 0;
}

.nexid-motion-frame .nexid-motion-glyph--bracelet .nexid-motion-glyph-body {
  inset: 42% 4% 42%;
}

.nexid-motion-nfc-band {
