}

.nexid-motion-proof-cluster {
  position: absolute;
  right: 4%;
  top: 16%;
  z-index: 4;
  display: grid;
  grid-template-columns: repeat(2, minmax(5rem, 1fr));
  gap: 0.55rem;
  width: min(42%, 21rem);
}

.nexid-motion-frame--story .nexid-motion-proof-cluster {
  left: 6%;
  right: 6%;
  top: auto;
  bottom: 28%;
  width: auto;
}

.nexid-motion-proof-cluster span {
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 0.85rem;
  background: rgba(15, 23, 42, 0.62);
  color: #cbd5e1;
