}

.nexid-motion-proof-cluster span.active {
  border-color: rgba(94, 234, 212, 0.42);
  background: rgba(20, 184, 166, 0.18);
  color: #ccfbf1;
}

.nexid-motion-script-rail {
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: 3.8%;
