  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: end;
  gap: 0.4rem;
  width: min(26%, 13rem);
  height: 7rem;
  border: 1px solid rgba(125, 211, 252, 0.14);
  border-radius: 0.9rem;
  background: rgba(2, 6, 23, 0.42);
  padding: 0.7rem;
  backdrop-filter: blur(12px);
}

.nexid-motion-frame--story .nexid-motion-chart {
  display: none;
}

.nexid-motion-chart span {
  --motion-bar: 50%;
  height: var(--motion-bar);
  min-height: 0.7rem;
  border-radius: 0.5rem 0.5rem 0.16rem 0.16rem;
  background: linear-gradient(180deg, #67e8f9, #14b8a6);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.2);
  animation: nexid-motion-bar 900ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.nexid-motion-glyph {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1.28;
  filter: drop-shadow(0 1.4rem 1.6rem rgba(2, 6, 23, 0.42));
}

.nexid-motion-glyph-body,
.nexid-motion-glyph-label,
.nexid-motion-glyph-seal {
  position: absolute;
  display: block;
}

.nexid-motion-glyph-body {
  inset: 12% 31% 7%;
  border: 1px solid rgba(251, 191, 36, 0.25);
  border-radius: 45% 45% 18% 18% / 16% 16% 8% 8%;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.22), transparent 18% 82%, rgba(255, 255, 255, 0.12)),
    linear-gradient(180deg, #f59e0b 0 18%, #14532d 18% 33%, #7f1d1d 33% 100%);
}

.nexid-motion-glyph-label {
  left: 38%;
  right: 38%;
  top: 58%;
  height: 16%;
  border-radius: 0.45rem;
