}

.nexid-motion-glyph-seal {
  left: 50%;
  top: 46%;
  width: 34%;
  height: 9%;
  transform: translateX(-50%) rotate(-6deg);
  border: 1px solid rgba(34, 211, 238, 0.72);
  border-radius: 0.45rem;
  background: rgba(2, 6, 23, 0.82);
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.22);
}

.nexid-motion-glyph--seeds .nexid-motion-glyph-body {
  inset: 16% 22% 8%;
  border-color: rgba(254, 240, 138, 0.34);
  border-radius: 1rem 1rem 0.65rem 0.65rem;
  background:
    radial-gradient(circle at 34% 70%, #facc15 0 0.3rem, transparent 0.32rem),
    radial-gradient(circle at 52% 76%, #facc15 0 0.24rem, transparent 0.26rem),
    linear-gradient(145deg, #15803d, #84cc16 54%, #facc15);
}

.nexid-motion-glyph--cream .nexid-motion-glyph-body {
  inset: 36% 18% 20%;
  border-radius: 1.2rem 1.2rem 2.4rem 2.4rem;
  background: linear-gradient(180deg, #e2e8f0 0 22%, #fff7ed 22% 40%, #fce7f3 40% 100%);
}

.nexid-motion-glyph--perfume .nexid-motion-glyph-body {
  inset: 16% 28% 9%;
  border-color: rgba(165, 180, 252, 0.36);
  border-radius: 1.2rem 1.2rem 0.85rem 0.85rem;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.3), transparent 22% 76%, rgba(255, 255, 255, 0.12)),
    linear-gradient(145deg, rgba(199, 210, 254, 0.86), rgba(91, 33, 182, 0.82));
}

.nexid-motion-glyph--bracelet .nexid-motion-glyph-body {
  inset: 42% 10% 42%;
  border-color: rgba(45, 212, 191, 0.42);
  border-radius: 999px;
  background: linear-gradient(90deg, #06b6d4, #14b8a6 48%, #8b5cf6);
  transform: rotate(-8deg);
}

.nexid-motion-glyph--ticket .nexid-motion-glyph-body {
  inset: 32% 9% 30%;
  border-color: rgba(251, 113, 133, 0.38);
  border-radius: 0.8rem;
  background:
    radial-gradient(circle at 0 50%, #071827 0 0.75rem, transparent 0.78rem),
    radial-gradient(circle at 100% 50%, #071827 0 0.75rem, transparent 0.78rem),
