  transform: rotate(-5deg);
}

.nexid-motion-products {
  padding-bottom: 0.5rem;
}

.nexid-motion-product-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.85rem;
}

.nexid-motion-product-card {
