  padding: 0.85rem;
}

.nexid-motion-product-card .nexid-motion-glyph {
  width: min(100%, 9rem);
  margin-inline: auto;
}

.nexid-motion-product-card small {
  display: block;
  margin-top: 0.7rem;
  color: #67e8f9;
  font-size: 0.58rem;
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
}

.nexid-motion-product-card strong {
  display: block;
  margin-top: 0.25rem;
  color: #f8fafc;
  font-size: 0.9rem;
  font-weight: 950;
}

.nexid-motion-product-card span {
  display: block;
  margin-top: 0.32rem;
  color: #94a3b8;
  font-size: 0.68rem;
  line-height: 1.45;
}

.nexid-motion-product-card em {
  display: inline-flex;
  margin-top: 0.6rem;
  font-size: 0.54rem;
}

.nexid-motion-storyboard {
  padding-bottom: clamp(2rem, 4vw, 4rem);
}

.nexid-motion-storyboard-rail {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.7rem;
}

.nexid-motion-storyboard-rail article {
  position: relative;
  min-height: 12rem;
  overflow: hidden;
  border: 1px solid rgba(125, 211, 252, 0.16);
  border-radius: 1.1rem;
  background:
    radial-gradient(circle at 20% 0, rgba(45, 212, 191, 0.16), transparent 40%),
    rgba(15, 23, 42, 0.58);
  padding: 0.85rem;
}

.nexid-motion-storyboard-rail article::after {
  content: "";
  position: absolute;
  inset: auto 0.85rem 0.85rem;
  height: 0.25rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #22d3ee, #5eead4, #a78bfa);
  opacity: 0.54;
}

.nexid-motion-storyboard-rail strong {
  display: block;
  margin-top: 1.4rem;
  color: #f8fafc;
  font-size: 1rem;
  font-weight: 950;
  line-height: 1.05;
}

.nexid-motion-storyboard-rail span {
  display: block;
  margin-top: 0.65rem;
  color: #cbd5e1;
  font-size: 0.72rem;
  line-height: 1.52;
}

@keyframes nexid-motion-scan {
  0%,
  26% {
    opacity: 0;
    transform: translateX(-80%);
  }

  44% {
    opacity: 1;
  }

  74%,
  100% {
    opacity: 0;
    transform: translateX(78%);
  }
}

@keyframes nexid-motion-product-float {
  0%,
  100% {
    transform: translate(-50%, -50%) translateY(0) rotate(-0.4deg);
  }

  50% {
    transform: translate(-50%, -50%) translateY(-0.7rem) rotate(0.5deg);
  }
}

@keyframes nexid-motion-bar {
  from {
    opacity: 0.55;
    transform: scaleY(0.28);
    transform-origin: bottom;
  }

  to {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: bottom;
  }
}

@keyframes nexid-motion-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(34, 211, 238, 0.34), 0 0 24px rgba(34, 211, 238, 0.46);
    transform: scale(0.82);
  }

  70% {
    box-shadow: 0 0 0 1.4rem rgba(34, 211, 238, 0), 0 0 28px rgba(34, 211, 238, 0.38);
    transform: scale(1);
  }

  100% {
    box-shadow: 0 0 0 0 rgba(34, 211, 238, 0), 0 0 18px rgba(34, 211, 238, 0.28);
    transform: scale(0.82);
  }
}

@keyframes nexid-motion-orbit {
  to {
    transform: translateX(-50%) rotate(342deg);
  }
}

@media (max-width: 1040px) {
