    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nexid-motion-purpose-grid {
    grid-template-columns: 1fr;
  }

  .nexid-motion-benchmark-grid,
  .nexid-motion-product-grid,
  .nexid-motion-storyboard-rail {
    grid-template-columns: 1fr;
  }

  .nexid-motion-frame--square,
  .nexid-motion-frame--wide {
    aspect-ratio: 9 / 12;
  }

  .nexid-motion-frame-product,
  .nexid-motion-frame--wide .nexid-motion-frame-product {
    left: 50%;
