/* Enterprise trust layers + product detail modal.
   The hero keeps a compact executive summary; dense product data lives in the modal. */
.enterprise-trust-layers__shell {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(103, 232, 249, 0.16);
  border-radius: 22px;
  background:
    radial-gradient(circle at 14% 8%, rgba(34, 211, 238, 0.14), transparent 32%),
    radial-gradient(circle at 86% 14%, rgba(16, 185, 129, 0.1), transparent 28%),
    linear-gradient(135deg, rgba(15, 23, 42, 0.94), rgba(2, 6, 23, 0.98));
  box-shadow: 0 32px 90px rgba(2, 8, 23, 0.34);
  padding: clamp(1.25rem, 2.5vw, 2rem);
}

.enterprise-trust-layers__head {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(280px, 0.72fr);
  gap: clamp(1rem, 3vw, 2rem);
  align-items: end;
}

.enterprise-trust-layers__head p {
  color: rgb(103, 232, 249);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
