.enterprise-trust-layers__head h2 {
  margin-top: 0.75rem;
  max-width: 54rem;
  color: white;
  font-size: clamp(2rem, 4.5vw, 4.6rem);
  font-weight: 950;
  line-height: 0.96;
  letter-spacing: 0;
}

.enterprise-trust-layers__head span {
  display: block;
  color: rgb(203, 213, 225);
  font-size: 0.95rem;
  line-height: 1.75;
}

.enterprise-trust-layers__head a {
  margin-top: 1rem;
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(103, 232, 249, 0.35);
  border-radius: 8px;
  background: rgba(8, 145, 178, 0.16);
  color: rgb(207, 250, 254);
