  overflow: hidden;
  text-decoration: none;
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.enterprise-trust-layer-card:focus-visible {
  outline: 2px solid rgba(103, 232, 249, 0.78);
  outline-offset: 3px;
}

.enterprise-trust-layer-card:hover,
.enterprise-trust-layer-card:focus-visible {
  transform: translateY(-2px);
}

.enterprise-trust-layer-card > div {
  display: flex;
  min-height: 2.4rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.enterprise-trust-layer-card > div > span {
  display: inline-flex;
  height: 2.25rem;
  width: 2.25rem;
  flex: none;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(34, 211, 238, 0.13);
  color: rgb(125, 211, 252);
}

.enterprise-trust-layer-card em {
  color: rgb(148, 163, 184);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-align: right;
  text-transform: uppercase;
}

.enterprise-trust-layer-card h3 {
  margin-top: 1rem;
  color: white;
  font-size: 1rem;
  font-weight: 950;
  line-height: 1.15;
}

.enterprise-trust-layer-card p {
  margin-top: 0.55rem;
  color: rgb(203, 213, 225);
  font-size: 0.78rem;
  line-height: 1.55;
}

.trust-layer-sim {
  margin-top: 0.9rem;
  min-height: 5.1rem;
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 8px;
  background:
    radial-gradient(circle at 18% 20%, rgba(34, 211, 238, 0.14), transparent 34%),
    rgba(2, 6, 23, 0.42);
  color: rgb(226, 232, 240);
  overflow: hidden;
  padding: 0.72rem;
  opacity: 0.84;
  transition: border-color 180ms ease, background 180ms ease, opacity 180ms ease;
}

.enterprise-trust-layer-card:hover .trust-layer-sim,
.enterprise-trust-layer-card:focus-visible .trust-layer-sim {
  border-color: rgba(103, 232, 249, 0.38);
  background:
    radial-gradient(circle at 20% 18%, rgba(34, 211, 238, 0.2), transparent 36%),
    rgba(2, 6, 23, 0.56);
  opacity: 1;
}

.trust-layer-sim strong,
.trust-layer-sim span,
.trust-layer-sim small {
  display: block;
  overflow-wrap: anywhere;
}

.trust-layer-sim--nfc {
  display: grid;
  grid-template-columns: 4.25rem minmax(0, 1fr);
  gap: 0.75rem;
  align-items: center;
}

.trust-layer-sim__scan {
  position: relative;
  display: grid;
  height: 3.8rem;
  place-items: center;
  border-radius: 999px;
  background: rgba(8, 145, 178, 0.16);
  box-shadow: inset 0 0 0 1px rgba(103, 232, 249, 0.25);
}

.trust-layer-sim__scan span {
  height: 2.2rem;
  width: 2.2rem;
  border-radius: 999px;
  background:
    repeating-radial-gradient(circle, rgba(103, 232, 249, 0.92) 0 1px, transparent 2px 5px);
}

.trust-layer-sim__scan i {
  position: absolute;
  left: 17%;
  right: 17%;
  top: 22%;
  height: 2px;
  background: rgb(103, 232, 249);
  box-shadow: 0 0 14px rgba(103, 232, 249, 0.72);
  animation: trust-layer-scan 2.4s ease-in-out infinite;
}

.trust-layer-sim__stack {
  display: grid;
  gap: 0.35rem;
}

.trust-layer-sim__stack strong,
.trust-layer-sim--offline strong,
.trust-layer-sim--tamper strong,
.trust-layer-sim--iot strong,
.trust-layer-sim--identity strong {
  color: rgb(236, 254, 255);
  font-size: 0.72rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.trust-layer-sim__stack span {
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.12);
  color: rgb(167, 243, 208);
  font-size: 0.68rem;
  font-weight: 800;
  overflow-wrap: normal;
  padding: 0.25rem 0.5rem;
  word-break: normal;
}

.trust-layer-sim--polygon {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.45rem;
}

.trust-layer-sim--polygon .trust-layer-sim__step {
  min-height: 3.5rem;
  border-radius: 8px;
  background: rgba(124, 58, 237, 0.16);
  color: rgb(221, 214, 254);
  font-size: 0.68rem;
  font-weight: 900;
  line-height: 1.2;
  overflow-wrap: normal;
  padding: 0.55rem;
  transform: translateY(5px);
  transition: transform 180ms ease, background 180ms ease;
  word-break: normal;
}

.trust-layer-sim--polygon small {
  margin-bottom: 0.4rem;
  color: rgb(196, 181, 253);
  font-size: 0.65rem;
}

.enterprise-trust-layer-card:hover .trust-layer-sim--polygon .trust-layer-sim__step,
.enterprise-trust-layer-card:focus-visible .trust-layer-sim--polygon .trust-layer-sim__step {
  transform: translateY(0);
}

.trust-layer-sim--polygon .trust-layer-sim__step--1 {
  transition-delay: 60ms;
}

.trust-layer-sim--polygon .trust-layer-sim__step--2 {
  transition-delay: 120ms;
}

.trust-layer-sim--iota {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 0.5rem;
}

.trust-layer-sim--iota::before {
  content: "";
  position: absolute;
  left: 1rem;
  right: 1rem;
  top: 1.45rem;
  height: 2px;
  background: linear-gradient(90deg, rgba(45, 212, 191, 0.24), rgba(45, 212, 191, 0.82), rgba(45, 212, 191, 0.24));
}

.trust-layer-sim--iota i {
  position: absolute;
  top: 1.14rem;
  left: 1rem;
  height: 0.66rem;
  width: 0.66rem;
  border-radius: 999px;
  background: rgb(45, 212, 191);
  box-shadow: 0 0 18px rgba(45, 212, 191, 0.8);
  animation: trust-layer-iota 3s ease-in-out infinite;
}

.trust-layer-sim--iota span {
  padding-top: 2.35rem;
  color: rgb(153, 246, 228);
  font-size: 0.68rem;
  font-weight: 900;
  overflow-wrap: normal;
  text-align: center;
  word-break: normal;
}

@media (max-width: 520px) {
  .trust-layer-sim {
    padding: 0.64rem;
  }

  .trust-layer-sim--nfc {
    grid-template-columns: minmax(3rem, 0.72fr) minmax(0, 1fr);
    gap: 0.55rem;
  }

  .trust-layer-sim__scan {
    height: 3.2rem;
  }

  .trust-layer-sim__scan span {
    height: 1.85rem;
    width: 1.85rem;
  }

  .trust-layer-sim__stack span {
    font-size: 0.62rem;
    line-height: 1.2;
    padding: 0.22rem 0.38rem;
  }

  .trust-layer-sim--polygon {
    grid-template-columns: minmax(0, 1fr);
  }

  .trust-layer-sim--polygon .trust-layer-sim__step {
    min-height: 2.6rem;
  }
}

.trust-layer-sim--offline,
.trust-layer-sim--tamper,
.trust-layer-sim--iot,
.trust-layer-sim--identity {
  display: grid;
  gap: 0.65rem;
  align-content: center;
}

.trust-layer-sim--offline div {
  display: flex;
  align-items: end;
  gap: 0.35rem;
  min-height: 2rem;
}

.trust-layer-sim--offline div span {
  width: 0.7rem;
  border-radius: 999px 999px 2px 2px;
  background: rgb(96, 165, 250);
}

.trust-layer-sim--offline div span:nth-child(1) { height: 0.65rem; opacity: 0.55; }
.trust-layer-sim--offline div span:nth-child(2) { height: 1.15rem; opacity: 0.75; }
.trust-layer-sim--offline div span:nth-child(3) { height: 1.75rem; animation: trust-layer-pulse 1.8s ease infinite; }

.trust-layer-sim--tamper span {
  position: relative;
  height: 1.65rem;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(248, 113, 113, 0.2), rgba(251, 191, 36, 0.86), rgba(248, 113, 113, 0.2));
}

.trust-layer-sim--tamper span::after {
  content: "";
  position: absolute;
  inset: 0.35rem 46% 0.35rem auto;
  width: 0.18rem;
  border-radius: 999px;
  background: rgb(254, 226, 226);
  box-shadow: 0 0 12px rgba(254, 226, 226, 0.7);
}

.trust-layer-sim--iot {
  grid-template-columns: repeat(4, 1fr);
  align-items: center;
}

.trust-layer-sim--iot span,
.trust-layer-sim--identity > span {
  height: 0.85rem;
  border-radius: 999px;
  background: rgba(103, 232, 249, 0.28);
  box-shadow: 0 0 14px rgba(103, 232, 249, 0.2);
  animation: trust-layer-pulse 2s ease infinite;
}

.trust-layer-sim--iot strong,
.trust-layer-sim--identity strong {
  grid-column: 1 / -1;
}

@keyframes trust-layer-scan {
  0%, 100% { transform: translateY(0); opacity: 0.45; }
  50% { transform: translateY(2rem); opacity: 1; }
}

@keyframes trust-layer-iota {
  0%, 100% { left: 1rem; }
  50% { left: calc(100% - 1.66rem); }
}

@keyframes trust-layer-pulse {
  0%, 100% { opacity: 0.55; transform: scaleY(0.82); }
  50% { opacity: 1; transform: scaleY(1); }
}

@media (prefers-reduced-motion: reduce) {
  .trust-layer-sim__scan i,
  .trust-layer-sim--iota i,
  .trust-layer-sim--offline div span,
  .trust-layer-sim--iot span,
  .trust-layer-sim--identity > span {
    animation: none !important;
  }
}

