.hero-trust-atlas__region-group--oceania .hero-trust-atlas__coastline {
  stroke: rgba(125, 211, 252, 0.22);
}

.hero-trust-atlas__route-halo {
  fill: none;
  stroke: rgba(2, 6, 23, 0.72);
  stroke-width: 13;
  stroke-linecap: round;
}

.hero-trust-atlas__route {
  fill: none;
  stroke-linecap: round;
  stroke-width: 3.2;
  stroke-dasharray: 15 18;
  animation: hero-atlas-route-flow 4.4s linear infinite;
}

.hero-trust-atlas__route--info {
  stroke: var(--hero-atlas-route-stroke, url(#hero-atlas-route-info));
}

.hero-trust-atlas__route--success {
  stroke: var(--hero-atlas-route-stroke, url(#hero-atlas-route-success));
  stroke-width: 4;
}

.hero-trust-atlas__route--warn {
  stroke: var(--hero-atlas-route-stroke, #f59e0b);
}

.hero-trust-atlas__comet {
