  opacity: 0.9;
}

.hero-trust-atlas__node-pulse {
  fill: rgba(34, 211, 238, 0.12);
  stroke: rgba(103, 232, 249, 0.22);
  stroke-width: 1.2;
  animation: hero-atlas-node-pulse 2.6s ease-in-out infinite;
}

.hero-trust-atlas__node-ring {
  fill: rgba(2, 8, 23, 0.78);
  stroke: rgba(103, 232, 249, 0.85);
  stroke-width: 2.4;
}

