/* Enterprise white-mode acceptance pass. These rules intentionally sit last:
   they remove dark islands without changing product flow, claims, or routes. */
.institutional-video-light-preview {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  background:
    radial-gradient(circle at 18% 30%, rgba(14, 165, 233, 0.18), transparent 30%),
    radial-gradient(circle at 88% 62%, rgba(16, 185, 129, 0.11), transparent 30%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.94), rgba(231, 249, 255, 0.92));
  padding: clamp(1rem, 2.4vw, 1.45rem);
  color: #0f172a;
  pointer-events: none;
}

.institutional-video-light-preview::before {
  content: "";
  position: absolute;
  inset: 0.75rem;
  border: 1px solid rgba(14, 116, 144, 0.14);
  border-radius: 14px;
  background:
    linear-gradient(90deg, rgba(14, 116, 144, 0.08) 0 1px, transparent 1px 100%),
    linear-gradient(180deg, rgba(14, 116, 144, 0.07) 0 1px, transparent 1px 100%);
  background-size: 32px 32px;
  mask-image: linear-gradient(135deg, black, transparent 76%);
}

