.institutional-video-light-preview > div:last-child {
  position: relative;
  z-index: 1;
}

.institutional-video-light-preview__chip {
  display: grid;
  width: clamp(3.4rem, 6vw, 5.2rem);
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid rgba(14, 116, 144, 0.18);
  border-radius: 18px;
  background:
    radial-gradient(circle at 35% 28%, rgba(255, 255, 255, 0.9), transparent 35%),
