}

.demo-lab-context-strip__trigger {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.25rem;
  color: rgba(148, 163, 184, 0.7);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
  user-select: none;
  transition: color 0.15s;
}
.demo-lab-context-strip__trigger::-webkit-details-marker { display: none; }
.demo-lab-context-strip__trigger:hover {
  color: #e0f2fe;
}

.demo-lab-context-strip__chevron {
  margin-left: auto;
  transition: transform 0.2s ease;
}
details[open] .demo-lab-context-strip__chevron {
  transform: rotate(90deg);
}

.demo-lab-context-strip__body {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  padding: 1rem 1.25rem 1.25rem;
  background: rgba(2, 8, 22, 0.6);
  border-top: 1px solid rgba(125, 211, 252, 0.07);
  animation: stripOpen 0.18s ease;
}
@keyframes stripOpen {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0);    }
}
@media (min-width: 768px) {
  .demo-lab-context-strip__body {
    grid-template-columns: 1fr 1fr auto;
    align-items: start;
  }
}

.demo-lab-context-strip__card {
  display: flex;
