.demo-lab-fullscreen-stage {
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.demo-lab-fullscreen-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%, rgba(34,211,238,0.07), transparent 70%),
    radial-gradient(ellipse 60% 50% at 80% 100%, rgba(139,92,246,0.06), transparent 60%);
