/* Override the DemoLabClient internal grid when inside full-screen stage */
.demo-lab-fullscreen-stage .demo-lab-studio {
  flex: 1;
  min-height: 0;
  height: 100%;
  border-radius: 0;
  border: none;
  border-top: 1px solid rgba(125, 211, 252, 0.08);
}

.demo-lab-fullscreen-stage .demo-lab-studio-grid {
  grid-template-columns:
    minmax(16rem, 0.72fr)
    minmax(32rem, 1.8fr)
    minmax(20rem, 0.88fr);
  height: 100%;
  min-height: calc(100dvh - 7rem);
}

/* Give the center stage more breathing room */
.demo-lab-fullscreen-stage .demo-lab-studio-stage {
